import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.DTwTvi8b.js";const g=JSON.parse('{"title":"0020 调度：用 Paseo 定时任务把消息发回对话，排队在本机进行","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0020-scheduling-through-the-chat.md","filePath":"reference/adr/0020-scheduling-through-the-chat.md","lastUpdated":null}'),d={name:"reference/adr/0020-scheduling-through-the-chat.md"};function s(i,e,c,h,n,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<div><h1 id="_0020-调度-用-paseo-定时任务把消息发回对话-排队在本机进行" tabindex="-1">0020 调度：用 Paseo 定时任务把消息发回对话，排队在本机进行 <a class="header-anchor" href="#_0020-调度-用-paseo-定时任务把消息发回对话-排队在本机进行" aria-label="Permalink to &quot;0020 调度：用 Paseo 定时任务把消息发回对话，排队在本机进行&quot;">​</a></h1><ul><li>状态：已采纳</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>需求开发要几个小时，使用者常常不在电脑前：希望晚上或明天早上再开始；限流中断后能自己接着做；等自己回答问题太久时有人提醒；同一台机器同时跑太多条流水线会抢资源和额度。</p><p>流水线进程是后台脚本，进程结束后就没有谁来做&quot;过一会儿再做某事&quot;。Paseo 的定时任务（schedules）由 daemon 保存，机器重启后仍然有效，可以在指定时间把一段话发进某个 agent 的对话，也可以按时间表启动新 agent。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li><strong>需要&quot;以后再做&quot;的事，都用 Paseo 定时任务把一条写明步骤的消息发回发起的对话</strong>，由对话 agent 执行 req-kit 的命令：预约开始（<code>--at</code>）、等待回答的提醒（<code>waitingReminderHours</code>）、临时错误后的自动继续（<code>autoResumeMinutes</code>，每次尝试最多 <code>autoResumeMax</code> 次）、可选的定时检查（<code>watchdogMinutes</code>，默认关闭）。消息先让对话 agent 查看进度，状态不符就什么也不做，所以重复或过期的消息无害。</li><li>这些定时任务记在状态文件中，下一次运行和暂停命令会取消它们；预约开始记在 <code>.pipeline/scheduled-start.json</code>。</li><li><strong>并发上限在本机实现</strong>（<code>maxConcurrentPipelines</code>，<code>~/.req-kit/slots/</code>）：排队的流水线进程自己等待名额，不需要 Paseo 参与。</li><li><strong>需求总览</strong>（<code>req digest</code>）发给外部通知；<code>--schedule</code> 用 Paseo 定时任务按时间表启动一个短暂的 agent 执行这条命令（会产生少量用量）。</li><li>Paseo 定时任务在 0.11 的公开 SDK 中还没有，和工作区脚本一样经由内部客户端调用（见 ADR 0017），不可用时这些功能自动关闭，并在输出中说明。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><p>使用者不在时，开发可以按时开始、出错后自己继续、等待太久会被提醒。每条定时消息会让对话 agent 运行一个回合，有少量用量；定时检查的回合最多，所以默认关闭。</p></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0020-scheduling-through-the-chat.md">docs/adr/0020-scheduling-through-the-chat.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0020-scheduling-through-the-chat.md">在 GitHub 上编辑</a></p>',2)])])}const p=a(d,[["render",s]]);export{g as __pageData,p as default};
